## Method and reasoning
Use two multisets. The lower half contains ceil(window size/2) elements, and every one is at most every element in the upper half. Insert into the appropriate half and rebalance by moving boundary values. Remove exactly one copy of the expiring value, from either half containing it. Equal copies are interchangeable. The maximum of the lower half is the answer.

## Walk through the sample
The first window sorted is [1,1,6,8], so its lower middle is the second 1. The last window sorts to [1,3,6,9], giving 3. Erasing all equal copies at once would break the half sizes.

## Complexity
Time O(n log(k+1)), space O(k) besides input storage.

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

class Median {
    multiset<int> low, high;
    void balance() {
        size_t target = (low.size() + high.size() + 1) / 2;
        while (low.size() > target) {
            auto it = prev(low.end());
            high.insert(*it);
            low.erase(it);
        }
        while (low.size() < target) {
            auto it = high.begin();
            low.insert(*it);
            high.erase(it);
        }
    }

  public:
    void add(int x) {
        if (low.empty() || x <= *low.rbegin())
            low.insert(x);
        else
            high.insert(x);
        balance();
    }
    void remove(int x) {
        auto it = low.find(x);
        if (it != low.end())
            low.erase(it);
        else
            high.erase(high.find(x));
        balance();
    }
    int middle() const { return *low.rbegin(); }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    Median median;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (i >= k)
            median.remove(a[i - k]);
        median.add(a[i]);
        if (i >= k - 1)
            cout << median.middle() << '\n';
    }
}
